statement:
You're given a binary tree where every node holds a number. In this problem a tree node is just a plain JavaScript object:

```js
{ val: 3, left: <node or null>, right: <node or null> }
```

Add up every `val` in the whole tree and return the total. If the tree is empty (`root` is `null`), return `0`.

**Function signature**

```js
function treeSum(root) {
  // root: a node object, or null
  // return a number
}
```

examples.input:
const root = {
  val: 3,
  left: {
    val: 11,
    left:  { val: 4,  left: null, right: null },
    right: { val: -2, left: null, right: null }
  },
  right: {
    val: 4,
    left: null,
    right: { val: 1, left: null, right: null }
  }
};
treeSum(root)

const root = {
  val: 1,
  left:  { val: 6, left: null, right: null },
  right: {
    val: 0,
    left:  { val: -4, left: null, right: null },
    right: null
  }
};
treeSum(root)

solution:
// CONTRACT for treeSum(root):
//     when this call returns, the returned value equals the total of
//     every node value in the tree whose root is `root` (an empty
//     tree returns 0).
const treeSum = (root) => {
    // Base case: an empty tree adds nothing.
    if (root === null) return 0;

    // Process node
    const currentNodeValue = root.val;

    // Recurse on children
    // The recursive leap of faith, one level down: this call has
    // the SAME contract — when it returns, `leftSubtreeSum` equals
    // the total of every node value in the left subtree. Trust it,
    // do not trace it. Own value + the two guaranteed subtree totals
    // = exactly this function's contract.
    const leftSubtreeSum = treeSum(root.left);
    // Same contract, one level down — trust it.
    const rightSubtreeSum = treeSum(root.right);

    return currentNodeValue + leftSubtreeSum + rightSubtreeSum;
};

// CONTRACT for hasPathSum(root, targetSum):
//     when this call returns, the returned value is true exactly
//     when some root-to-leaf path in the tree whose root is `root`
//     adds up to `targetSum`, and false otherwise.
const hasPathSum = (root, targetSum) => {
    // Base case: an empty tree has no root-to-leaf paths at all.
    if (root === null) return false;

    // Process node: this node uses up part of the target.
    const remainingSum = targetSum - root.val;

    // A path is only complete at a leaf, so only a leaf may declare success.
    const isLeaf = root.left === null && root.right === null;
    if (isLeaf) return remainingSum === 0;

    // Recurse on children
    // The recursive leap of faith, one level down: each of these two
    // calls has the SAME contract — when it returns, its value is true
    // exactly when that child's subtree has a root-to-leaf path adding
    // up to `remainingSum`. Trust them, do not trace them. This node
    // already used up its own value, so left-answer OR right-answer is
    // exactly this function's contract.
    return (
        hasPathSum(root.left, remainingSum) ||
        hasPathSum(root.right, remainingSum)
    );
};

statement:
You're given a non-empty binary tree where every node holds a number. Each node is a plain JavaScript object:

```js
{ val: 3, left: <node or null>, right: <node or null> }
```

A **root-to-leaf path** starts at the root and repeatedly steps to a child until it reaches a **leaf** — a node with no children (`left` and `right` both `null`). The path's sum is the total of all `val`s along it, including the root's and the leaf's.

Return the largest sum among all root-to-leaf paths. Watch out: values can be negative, and a path is only allowed to stop at a leaf.

**Function signature**

```js
function maxPathSum(root) {
  // root: a node object (never null)
  // return a number
}
```

examples.input:
const root = {
  val: 3,
  left: {
    val: 11,
    left:  { val: 4,  left: null, right: null },
    right: { val: -2, left: null, right: null }
  },
  right: {
    val: 4,
    left: null,
    right: { val: 1, left: null, right: null }
  }
};
maxPathSum(root)

const root = {
  val: 2,
  left: {
    val: -1,
    left:  { val: 4, left: null, right: null },
    right: { val: 7, left: null, right: null }
  },
  right: { val: 10, left: null, right: null }
};
maxPathSum(root)

solution:
// CONTRACT for maxPathSum(root):
//     when this call returns, the returned value equals the largest
//     possible total of node values on any path from `root` down to
//     a leaf. `root` here means whatever node this call was handed —
//     each recursive call gets its own.
const maxPathSum = (root) => {
    // Base case: a path may only stop at a leaf, so a leaf's best path
    // is simply its own value.
    const isLeaf = root.left === null && root.right === null;
    if (isLeaf) return root.val;

    // Process node

    // Recurse on children
    // Values can be negative, so a missing child is skipped entirely
    // rather than treated as a 0-valued path.
    const childPathSums = [];

    // The recursive leap of faith, one level down: this call has
    // the SAME contract — when it returns, its value equals the best
    // root-to-leaf total inside the left subtree. Trust it, do not
    // trace it. Own value + the best of the children's guaranteed
    // totals = exactly this function's contract.
    if (root.left !== null) childPathSums.push(maxPathSum(root.left));
    // Same contract, one level down — trust it.
    if (root.right !== null) childPathSums.push(maxPathSum(root.right));

    return root.val + Math.max(...childPathSums);
};

const TRUE_NODE = 1;
const OR_NODE = 2;
const AND_NODE = 3;

// CONTRACT for evaluateTree(root):
//     when this call returns, the returned value is the single
//     true/false answer that the whole tree under `root` boils
//     down to. `root` here means whatever node this call was
//     handed — each recursive call gets its own.
const evaluateTree = (root) => {
    // Base case: a childless node's true/false value is its own meaning.
    const isLeaf = root.left === null && root.right === null;
    if (isLeaf) return root.val === TRUE_NODE;

    // Process node: a parent's value names the operator it applies.
    const isAndNode = root.val === AND_NODE;

    // Recurse on children
    // The recursive leap of faith, one level down: this call has
    // the SAME contract — when it returns, `leftChildValue` is the
    // true/false answer of the entire left subtree. Trust it, do not
    // trace it. This node's operator applied to the two guaranteed
    // child answers = exactly this function's contract.
    const leftChildValue = evaluateTree(root.left);
    // Same contract, one level down — trust it.
    const rightChildValue = evaluateTree(root.right);

    // An AND node needs both children true; an OR node needs at least one.
    if (isAndNode) return leftChildValue && rightChildValue;

    return leftChildValue || rightChildValue;
};
